import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_LIMIT = 1000100;
    static final int INF_LIMIT = 1000000007;
    static final int MOD_LIMIT = 1000000007;
    static final int P_CONST = 6151;
    static final int T_CONST = 2000;
    static final int SQ_CONST = 280;
    static final int LOG_SZ = 64;
    static final int LOG2_SZ = 34;

    static int total_num, base_d;
    static List<Integer> digits = new ArrayList<>();

    static class Node {
        int[][] mat = new int[LOG2_SZ][LOG2_SZ];
        int[][] temp = new int[LOG2_SZ][LOG2_SZ];
        boolean[] visited = new boolean[LOG2_SZ];
        boolean[] toggled = new boolean[LOG2_SZ];

        void combine(Node other) {
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    mat[i][j] = 0;
                    for (int k = 0; k <= base_d; k++) {
                        mat[i][j] = (int)((mat[i][j] + (long)mat[k][j] * other.mat[i][k]) % MOD_LIMIT);
                    }
                }
            }
            for (int i = 0; i < base_d; i++) {
                if (visited[i] && !other.visited[i]) {
                    for (int j = 0; j <= base_d; j++) {
                        mat[i][j] = mat[i][j];
                    }
                }
                if (!visited[i] && other.visited[i]) {
                    for (int j = 0; j <= base_d; j++) {
                        mat[j][i] = other.mat[j][i];
                    }
                }
                visited[i] |= other.visited[i];
            }
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    mat[i][j] = mat[i][j];
                }
            }
        }

        void reset() {
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    mat[i][j] = 0;
                    temp[i][j] = 0;
                }
            }
        }

        void shift(int shift_value) {
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    temp[i][j] = 0;
                }
            }
            for (int i = 0; i < base_d; i++) {
                for (int j = 0; j < base_d; j++) {
                    int ni = (i + shift_value) % base_d;
                    int nj = (j + shift_value) % base_d;
                    temp[ni][nj] = mat[i][j];
                }
                temp[(i + shift_value) % base_d][base_d] = mat[i][base_d];
            }
            for (int i = 0; i < base_d; i++) {
                temp[base_d][(i + shift_value) % base_d] = mat[base_d][i];
            }
            temp[base_d][base_d] = mat[base_d][base_d];

            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    mat[i][j] = temp[i][j];
                }
            }

            for (int i = 0; i < base_d; i++) {
                toggled[i] = visited[(i + shift_value) % base_d];
            }
            for (int i = 0; i < base_d; i++) {
                visited[i] = toggled[i];
            }
        }
    }

    static Node[] node_arr = new Node[LOG_SZ];
    static Node[] helper_arr = new Node[LOG_SZ];
    static Node temp_node_obj = new Node();

    static Node fetch_node(int x) {
        int h = x, pw = 1, t_idx = -1;
        while (h >= base_d) {
            h /= base_d;
            pw *= base_d;
            t_idx++;
        }
        x %= pw;
        if (t_idx == -1) {
            return helper_arr[h];
        }
        Node res_node = node_arr[t_idx];
        temp_node_obj = node_arr[t_idx];
        for (int i = 1; i < h; i++) {
            temp_node_obj.shift(1);
            res_node.combine(temp_node_obj);
        }
        temp_node_obj = node_arr[t_idx];
        temp_node_obj = fetch_node(x);
        temp_node_obj.shift(h);
        res_node.combine(temp_node_obj);
        return res_node;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Initialize nodes
        for (int i = 0; i < LOG_SZ; i++) {
            node_arr[i] = new Node();
            helper_arr[i] = new Node();
        }

        int totalNum = sc.nextInt();
        base_d = sc.nextInt();
        totalNum--;
        int tempTotal = totalNum;
        while (totalNum > 0) {
            digits.add(totalNum % base_d);
            totalNum /= base_d;
